#pragma once

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

// Netscan's pure logic (no ESP-IDF dependency): tested on the PC
// with test/host.

// --- MAC and vendor ---

// "Private" MAC (locally administered): phones and PCs with a random address,
// so the OUI vendor means nothing.
bool ns_mac_is_private(const uint8_t mac[6]);
void ns_mac_str(const uint8_t mac[6], char out[18]);

// Looks up the vendor in an oui.bin file (generated by tools/make_oui.py): "OUI1",
// record count (u32 little endian), then 32-byte records sorted by
// OUI (3 bytes + 29-byte NUL-padded name). false if not found.
bool ns_oui_lookup(FILE *f, const uint8_t mac[6], char *out, size_t n);

// --- Host names ---

// NBNS "node status" request (UDP 137) with the wildcard name. Returns the length (50).
int ns_nbns_query(uint8_t buf[50]);
// Extracts the machine's NetBIOS name from the response. false if missing.
bool ns_nbns_parse(const uint8_t *buf, int len, char *name, size_t n);

// mDNS "PTR x.x.x.x.in-addr.arpa" request to send as unicast to the host's
// port 5353 (RFC 6762 §5.5: a responder also answers senders that do not use
// port 5353). Returns the length.
int ns_mdns_ptr_query(uint8_t *buf, size_t n, const uint8_t ip[4]);
// Extracts the name (without ".local") from the response. false if missing.
bool ns_mdns_ptr_parse(const uint8_t *buf, int len, char *name, size_t n);

// --- DHCP ---

// A received DHCP offer. Addresses in network order (as on the wire).
typedef struct {
    uint8_t server[4];  // server identifier (option 54), or the source IP if missing
    uint8_t offered[4]; // yiaddr
    uint8_t mask[4], router[4], dns[4]; // zero if the option is missing
    uint32_t lease_s;   // 0 if the option is missing
} ns_dhcp_offer_t;

// DHCPDISCOVER with the broadcast flag (OFFERs arrive at 255.255.255.255,
// so even a raw socket without a server-assigned IP sees them), already
// inside a UDP 68 -> 67 header with the checksum for `src` -> 255.255.255.255.
// To be sent on an IPPROTO_UDP raw socket. Returns the length (0 if `n`
// is too small).
int ns_dhcp_discover(uint8_t *buf, size_t n, const uint8_t mac[6], uint32_t xid, const uint8_t src[4]);
// Parses a whole IPv4 packet (as returned by a raw socket): true
// if it is a 67 -> 68 DHCPOFFER with this `xid`.
bool ns_dhcp_parse_offer(const uint8_t *pkt, int len, uint32_t xid, ns_dhcp_offer_t *out);

// --- Text ---

// Copies only printable ASCII (anything else becomes '?', once per UTF-8
// character): the SSID and a host's name are chosen by whoever is on the network.
void ns_display_text(char *dst, size_t n, const char *src);
// CSV field: quotes if needed and an apostrophe before =,+,-,@ (Excel would
// run them as formulas: SSIDs and names come from the network).
// Returns the length written (always NUL-terminated).
size_t ns_csv_field(char *dst, size_t n, const char *src);
// File name fragment: only [A-Za-z0-9_-], at most n-1 characters.
void ns_file_slug(char *dst, size_t n, const char *src);

// --- Sweep ---

// Range of hosts to query (host order, bounds included) for
// address `ip` and mask `mask`: the actual network, but never larger than
// the /24 containing `ip`. false if the network has no usable hosts.
bool ns_sweep_range(uint32_t ip, uint32_t mask, uint32_t *first, uint32_t *last);
